package com.example.waterfilter;
import android.app.*;import android.content.*;import android.os.Build;import androidx.core.app.NotificationCompat;
public class ReminderReceiver extends BroadcastReceiver{
 @Override public void onReceive(Context c,Intent i){if(!c.getSharedPreferences(MainActivity.PREFS,0).getBoolean(MainActivity.ENABLED_KEY,true))return;showNotification(c,i.getStringExtra("title"),i.getStringExtra("message"));}
 static void showNotification(Context c,String title,String message){Intent open=new Intent(c,MainActivity.class);open.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);int flags=PendingIntent.FLAG_UPDATE_CURRENT;if(Build.VERSION.SDK_INT>=23)flags|=PendingIntent.FLAG_IMMUTABLE;PendingIntent pi=PendingIntent.getActivity(c,11,open,flags);Notification n=new NotificationCompat.Builder(c,MainActivity.CHANNEL_ID).setSmallIcon(R.drawable.ic_stat_water).setContentTitle(title==null?"متابع فلتر المياه":title).setContentText(message==null?"راجع مواعيد صيانة الفلتر":message).setStyle(new NotificationCompat.BigTextStyle().bigText(message)).setPriority(NotificationCompat.PRIORITY_HIGH).setCategory(NotificationCompat.CATEGORY_REMINDER).setAutoCancel(true).setContentIntent(pi).setDefaults(NotificationCompat.DEFAULT_ALL).build();((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify((int)(System.currentTimeMillis()&0x7fffffff),n);}
}
